import bpy
ns=bpy.app.driver_namespace['harbor_craft']
exec("# Correct join-layer loss: every editable piece uses one consistently named UV layer.
for o in c.objects:
    if o.type=='MESH' and o.data.uv_layers:
        o.data.uv_layers.active.name='CraftUV'
    if o.name.startswith('Rafter tail'):
        o.location.z-=.19
    if o.name.startswith(('Front siding','Side siding','Rear siding')):
        # Actual small seams; avoid coplanar overlapping board faces.
        for v in o.data.vertices:v.co.y*=.93
    if o.name.startswith('Gable ') and not o.name.startswith(('Gable fascia','Gable vent')):
        for v in o.data.vertices:v.co.y*=.95
    if o.name.startswith('Roof course'):
        # The lower exposed edge is thicker than the tucked upper edge.
        side=int(o.name.split()[2])
        for v in o.data.vertices:v.co.z+=.045*v.co.y*side
    if o.name.startswith('Canopy diagonal brace'):
        # Connect to the underside of the canopy, not through the upper boards.
        o.location.z-=.10
    if o.name.startswith('Net '):
        for v in o.data.vertices:
            u=(v.co.y+3.02)/3.02
            v.co.y+=.018*math.sin(u*15+v.co.z*4)*math.sin(math.pi*max(0,min(1,u)))
# Remove the middle-front platform pile from the doorway route; its bearer remains.
for o in list(c.objects):
    if o.name.startswith('Square dock pile (-4.37, 0)'):
        bpy.data.objects.remove(o,do_unlink=True)
    elif o.name.startswith('Pile endgrain cap') and abs(o.location.x+4.485)<.03 and abs(o.location.y)<.01:
        bpy.data.objects.remove(o,do_unlink=True)
# Correct wood tube UVs (barrel rim) into a timber slot.
for o in c.objects:
    if o.type=='MESH' and o.data.materials and o.data.materials[0]==wood and 'rim' in o.name.lower():
        for uv in o.data.uv_layers.active.data:
            u,v=uv.uv;uv.uv=uvslot(23,u%1,v)
# New copies preserve the now common UV layer when joined by material.
export_asset()
